{"function":"async () => {
  const res = await fetch('/listing/api/status/feeds/download?batchId=284428020756&merchantId=amzn1.merchant.o.A2O6EHY2KJ4BXE&frpRegion=NA');
  const buf = await res.arrayBuffer();
  const bytes = new Uint8Array(buf);

  // Simple ZIP parser
  let offset = 0;
  const files = {};

  while (offset < bytes.length - 4) {
    const sig = bytes[offset] | (bytes[offset+1] << 8) | (bytes[offset+2] << 16) | (bytes[offset+3] << 24);
    if (sig === 0x04034b50) { // Local file header
      const compMethod = bytes[offset+8] | (bytes[offset+9] << 8);
      const compSize = bytes[offset+18] | (bytes[offset+19] << 8) | (bytes[offset+20] << 16) | (bytes[offset+21] << 24);
      const uncompSize = bytes[offset+22] | (bytes[offset+23] << 8) | (bytes[offset+24] << 16) | (bytes[offset+25] << 24);
      const nameLen = bytes[offset+26] | (bytes[offset+27] << 8);
      const extraLen = bytes[offset+28] | (bytes[offset+29] << 8);

      const nameBytes = bytes.slice(offset + 30, offset + 30 + nameLen);
      const fileName = new TextDecoder().decode(nameBytes);
      const dataStart = offset + 30 + nameLen + extraLen;
      const compData = bytes.slice(dataStart, dataStart + compSize);

      files[fileName] = { compMethod, compSize, uncompSize, compData };
      offset = dataStart + compSize;
    } else {
      offset++;
    }
  }

  // Decompress function using DecompressionStream
  async function decompress(compData, compMethod) {
    if (compMethod === 0) return new TextDecoder().decode(compData);
    if (compMethod === 8) {
      const ds = new DecompressionStream('deflate-raw');
      const writer = ds.writable.getWriter();
      writer.write(compData);
      writer.close();
      const reader = ds.readable.getReader();
      const chunks = [];
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        chunks.push(value);
      }
      const totalLen = chunks.reduce((acc, c) => acc + c.length, 0);
      const resBytes = new Uint8Array(totalLen);
      let pos = 0;
      for (const c of chunks) {
        resBytes.set(c, pos);
        pos += c.length;
      }
      return new TextDecoder().decode(resBytes);
    }
    return `Unsupported method ${compMethod}`;
  }

  const fileList = Object.keys(files);
  let summary = "";
  let sharedStrings = "";
  if (files['xl/sharedStrings.xml']) {
    sharedStrings = await decompress(files['xl/sharedStrings.xml'].compData, files['xl/sharedStrings.xml'].compMethod);
  }

  // Find sheets
  const sheetNames = fileList.filter(f => f.startsWith('xl/worksheets/'));
  const sheetContents = {};
  for (const s of sheetNames) {
    sheetContents[s] = (await decompress(files[s].compData, files[s].compMethod)).slice(0, 1000);
  }

  return {
    fileList,
    sharedStringsSample: sharedStrings.slice(0, 3000),
    sharedStringsLength: sharedStrings.length,
    sheets: sheetContents
  };
}","pageId":17,"toolSummary":"Parse zip xlsx processing summary","waitForStableDom":false}

