tool_calls.arguments_json:
{"function":"() => {
  const parents = [];
  const links = document.querySelectorAll('a[href*="skucentral?mSku=PARENT-4A"]');
  links.forEach(a => {
    const sku = a.innerText.trim();
    // look around for ASIN and variation count
    let p = a.parentElement;
    for (let i = 0; i < 6 && p; i++) {
      const text = p.innerText || "";
      if (text.includes("Parent ASIN") || text.includes("变体")) break;
      p = p.parentElement;
    }
    const fullText = p ? p.innerText : "";
    const asinMatch = fullText.match(/(?:Parent ASIN:|ASIN)\s*[:\n\r]*([A-Z0-9]{10})/i);
    const varCountMatch = fullText.match(/变体\s*\((\d+)\)/);
    parents.push({
      sku,
      asin: asinMatch ? asinMatch[1] : null,
      variationCount: varCountMatch ? parseInt(varCountMatch[1], 10) : 0
    });
  });
  // remove duplicates
  const unique = [];
  const seen = new Set();
  for (const item of parents) {
    if (!seen.has(item.sku)) {
      seen.add(item.sku);
      unique.push(item);
    }
  }
  return unique;
}","pageId":33,"toolSummary":"List parent families on Page 1","waitForStableDom":false}

