  await new Promise(r => setTimeout(r, 2000));
  const text = document.body.innerText;
  const blocks = text.split(/变体系列[:：]/);
  const families = [];
  for (let i = 1; i < blocks.length; i++) {
    const block = blocks[i];
    const asinMatch = block.match(/(?:Parent ASIN|ASIN)[:：\s]+([A-Z0-9]{10})/i);
    const skuMatch = block.match(/(?:父 SKU|SKU)[:：\s]+([A-Z0-9_-]+)/i);
    const varMatch = block.match(/变体\s*\((\d+)\)/);
    families.push({
      parentAsin: asinMatch ? asinMatch[1] : null,
      parentSku: skuMatch ? skuMatch[1] : null,
      childCount: varMatch ? parseInt(varMatch[1], 10) : 0
    });
  }
  return families;
}

